using System.Windows;using System.Windows.Controls;using LabMaster.Services;namespace LabMaster;public partial class QCWindow:Window{readonly QCService service=new();QCRow? selected;public QCWindow(){InitializeComponent();Loaded+=async(_,_)=>await LoadAsync();}async Task LoadAsync(){try{Grid.ItemsSource=await service.GetAsync();StatusText.Text="Select a QC material, enter the observed value, then save."; }catch(Exception ex){MessageBox.Show(ex.Message,"Lab Master",MessageBoxButton.OK,MessageBoxImage.Error);}}void Grid_SelectionChanged(object s,SelectionChangedEventArgs e){selected=Grid.SelectedItem as QCRow;if(selected!=null){ResultBox.Focus();ResultBox.Clear();}}async void SaveResult_Click(object s,RoutedEventArgs e){if(selected==null){MessageBox.Show("Select a QC material.");return;}if(!decimal.TryParse(ResultBox.Text,out var value)){MessageBox.Show("Enter a valid QC result.");return;}try{var flag=await service.EvaluateAsync(selected.Id,value);FlagText.Text=$"QC Status: {flag}";if(flag=="REJECT"){MessageBox.Show("QC result is outside ±3 SD. Review the run before reporting patient results.","QC Warning",MessageBoxButton.OK,MessageBoxImage.Warning);}await service.SaveResultAsync(selected.Id,value,string.IsNullOrWhiteSpace(CommentBox.Text)?null:CommentBox.Text.Trim());MessageBox.Show("QC result saved.","Lab Master",MessageBoxButton.OK,MessageBoxImage.Information);ResultBox.Clear();CommentBox.Clear();}catch(Exception ex){MessageBox.Show(ex.Message,"Lab Master",MessageBoxButton.OK,MessageBoxImage.Error);}}async void History_Click(object s,RoutedEventArgs e){if(selected==null){MessageBox.Show("Select a QC material first.");return;}new QCHistoryWindow(selected.Id,selected.Material){Owner=this}.ShowDialog();}async void Add_Click(object s,RoutedEventArgs e){var w=new AddQCWindow{Owner=this};if(w.ShowDialog()==true)await LoadAsync();}}